import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import { formatedatetime, formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import { list_expense_transactions } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import ViewExpenses from "./ExpensePopups/ViewExpenses.vue";
import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { getS3SignedUrl } from "@/mixins/S3GetStorageFile.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  name: "PettyCashTransaction",
  props: {
    currentBalance: {
      type: Number,
      default: 0
    },
    fromDate: {
      type: String,
      default: ""
    },
    toDate: {
      type: String,
      default: ""
    },
    statusType: {
      type: String,
      default: "ALL"
    },
    selectedUser: {
      type: String,
      default: "ALL"
    }
  },
  components: {
    SnackBar,
    ViewExpenses
  },
  mixins: [get_Org_details, get_all_org_users],
  data() {
    let today = new Date();
    let lastMonth = new Date();
    lastMonth.setMonth(today.getMonth() - 1);
    return {
      fixed: true,
      expenseView: false,
      modal: false,
      endmodal: false,
      date: lastMonth.toISOString().substr(0, 10),
      todate: today.toISOString().substr(0, 10),
      tableData: [],
      rowInfo: {},
      selectStatusType: this.statusType,
      selectTransactionType: "PETTY_CASH",
      SnackBarComponent: {},
      tableLoading: false,
      componentCheck: 0,
      height: 0,
      headers: [{
        title: "Category",
        value: "category_id_text",
        sortable: false
      }, {
        title: "Group Name",
        value: "expense_group_id_text",
        sortable: false
      }, {
        title: "Project Name",
        value: "project_id_text",
        sortable: false
      }, {
        title: "Member Name ",
        value: "user_id_text",
        sortable: false
      },
      // {
      //   title: "Transaction Type",
      //   value: "transaction_type",
      //   sortable: false,
      // },
      {
        title: "Amount",
        value: "amount",
        sortable: false
      }, {
        title: "Bill Date",
        value: "bill_date",
        sortable: false
      }, {
        title: "Initiated On",
        value: "transaction_created_on",
        sortable: false
      }, {
        title: "Status",
        value: "transaction_status",
        sortable: false
      }, {
        title: "Pending On",
        value: "pending_on",
        sortable: false
      }, {
        title: "Documents",
        value: "docs",
        sortable: false
      }],
      goLoading: false,
      datePicker: false,
      datePickerTo: false,
      tempDate: lastMonth.toISOString().substr(0, 10),
      tempDateTo: today.toISOString().substr(0, 10),
      searchQuery: "",
      currentPage: 1,
      itemsPerPage: 10,
      pageCount: 0,
      allUSersNames: []
    };
  },
  computed: {
    computedDateDisplay() {
      return this.dateformating(this.date);
    },
    dataDisplayFormatted() {
      return this.dateformating(this.todate);
    },
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.tableData.filter(item => item.category_id_text && item.category_id_text.toLowerCase().includes(searchTerm) || item.expense_group_id_text && item.expense_group_id_text.toLowerCase().includes(searchTerm) || item.project_id_text && item.project_id_text.toLowerCase().includes(searchTerm) || item.user_id_text && item.user_id_text.toLowerCase().includes(searchTerm) || item.transaction_type && item.transaction_type.toLowerCase().includes(searchTerm) || item.transaction_status && item.transaction_status.toLowerCase().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    // Watch for prop changes
    fromDate(newVal) {
      if (newVal) {
        this.date = this.parseDateFromDisplay(newVal);
        this.getexpense_list();
      }
    },
    toDate(newVal) {
      if (newVal) {
        this.todate = this.parseDateFromDisplay(newVal);
        this.getexpense_list();
      }
    },
    statusType(newVal) {
      this.selectStatusType = newVal;
      this.getexpense_list();
    },
    transactionType(newVal) {
      this.selectTransactionType = newVal;
      this.getexpense_list();
    }
  },
  mounted() {
    this.height = window.innerHeight - 250;
  },
  async created() {
    this.height = window.innerHeight - 250;
    this.tableLoading = true;
    await this.get_Org_details();
    await this.get_initiated_expense();
    await this.get_all_org_users();
    this.allUSersNames = this.orgUsers;
  },
  methods: {
    getFirstInProgressUser(data) {
      // Sort based on step_no in ascending order
      data.sort((a, b) => a.step_no - b.step_no);

      // Iterate over sorted data to find the first step with 'INPROGRESS' status
      for (let i = 0; i < data.length; i++) {
        if (data[i].approval_status === "INPROGRESS") {
          return this.fetch_user_name(data[i].user_email_id); // Return the user_email_id of the first 'INPROGRESS' step
        }
      }

      // If no step with 'INPROGRESS', return null
      return '-';
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      if (value == "SYSTEM") {
        name = value;
      }
      return name;
    },
    getAmountValue(item) {
      // If entry_type is REFILL, use granted_amount, otherwise use amount
      if (item.entry_type === "REFILL") {
        return item.granted_amount || "0";
      }
      return item.amount || "0";
    },
    displayFormatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    parseDateFromDisplay(displayDate) {
      // Convert DD/MM/YYYY to YYYY-MM-DD
      if (!displayDate) return "";
      const parts = displayDate.split("/");
      if (parts.length === 3) {
        return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
      return displayDate;
    },
    saveDate() {
      this.date = this.tempDate;
      this.datePicker = false;
    },
    saveDateTo() {
      this.todate = this.tempDateTo;
      this.datePickerTo = false;
    },
    getexpense_list() {
      this.tableData = [];
      this.goLoading = true;
      this.get_initiated_expense();
      // Emit filter applied event
      this.$emit("filter-applied", {
        fromDate: this.computedDateDisplay,
        toDate: this.dataDisplayFormatted,
        statusType: this.selectStatusType,
        transactionType: this.selectTransactionType,
        selectedUser: this.selectedUser
      });
    },
    // Method to handle filter changes from parent component
    handleFilterChange(filterData) {
      if (filterData.fromDate) {
        this.date = this.parseDateFromDisplay(filterData.fromDate);
      }
      if (filterData.toDate) {
        this.todate = this.parseDateFromDisplay(filterData.toDate);
      }
      if (filterData.statusType) {
        this.selectStatusType = filterData.statusType;
      }
      if (filterData.transactionType) {
        this.selectTransactionType = filterData.transactionType;
      }
      if (filterData.selectedUser) {
        this.selectedUser = filterData.selectedUser;
      }
      this.getexpense_list();
    },
    get_date1(val) {
      var data = formatdisplayDate(val);
      return data;
    },
    show_file(item) {
      if (["jpg", "jpeg", "img", "png"].indexOf(String(item.media_keys.split(".").pop())) > -1) {
        this.componentCheck = 1;
        this.rowInfo = item;
        this.expenseView = true;
      } else {
        this.pdf = this.s3get(item);
        window.open(this.pdf);
      }
    },
    s3get(item) {
      var s3Bucket = new AWS.S3({
        region: this.orgDetails.s3_details.region,
        accessKeyId: this.orgDetails.s3_details.access_key,
        secretAccessKey: this.orgDetails.s3_details.secret_key,
        signatureVersion: "v4"
      });
      var params = {
        Bucket: this.orgDetails.s3_details.bucket_name,
        Key: "workflow/" + item.media_keys.split("workflow/")[1],
        Expires: 6000 * 5
      };
      var url = s3Bucket.getSignedUrl("getObject", params);
      return url;
    },
    get_date(date) {
      return formatedatetime(date);
    },
    dateformating(todate) {
      if (!todate) return "";
      const d = new Date(todate);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${day}/${month}/${year}`;
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    getcal() {
      this.modal = true;
    },
    getStatusColor(status) {
      switch (status) {
        case "APPROVED":
          return "green";
        case "PENDING":
          return "orange";
        case "WITHDRAWN":
          return "blue";
        case "REJECTED":
          return "red";
        default:
          return "grey";
      }
    },
    getStatusIcon(status) {
      switch (status) {
        case "APPROVED":
          return "mdi-check-circle";
        case "PENDING":
          return "mdi-clock-outline";
        case "WITHDRAWN":
          return "mdi-undo";
        case "REJECTED":
          return "mdi-close-circle";
        default:
          return "mdi-help-circle";
      }
    },
    getStatusTextColor(status) {
      switch (status) {
        case "APPROVED":
          return "green--text";
        case "PENDING":
          return "orange--text";
        case "WITHDRAWN":
          return "primary--text";
        case "REJECTED":
          return "red--text";
        default:
          return "grey--text";
      }
    },
    async get_initiated_expense() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;

      // Convert display dates to API format if they come from props
      let startTime = this.date;
      let endTime = this.todate;

      // If we have props with display format dates, convert them
      if (this.fromDate && this.fromDate.includes("/")) {
        startTime = this.parseDateFromDisplay(this.fromDate);
      }
      if (this.toDate && this.toDate.includes("/")) {
        endTime = this.parseDateFromDisplay(this.toDate);
      }
      try {
        let result = await API.graphql(graphqlOperation(list_expense_transactions, {
          input: {
            transaction_by: this.selectedUser == 'ALL' ? undefined : this.selectedUser,
            user_email_id: data.user.user_email_id,
            nextToken: null,
            limit: 100,
            organization_id: data.organization.organization_id,
            start_time: this.formatDate(startTime),
            end_time: this.formatDate(endTime),
            transaction_status: this.selectStatusType == 'ALL' ? undefined : this.selectStatusType,
            transaction_type: "PETTY_CASH"
          }
        }));
        var response = JSON.parse(result.data.list_expense_transactions);
        this.tableLoading = false;
        this.goLoading = false;
        // console.log(response);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.goLoading = false;
          this.tableData = response.data;
          // console.log("PettyCashTransaction Response:", response);
          this.$emit('balance-updated', response.org_wallet);
          this.totalItems = response.data.length;
          this.pageCount = Math.ceil(this.totalItems / this.itemsPerPage);
        } else {
          this.tableLoading = false;
          this.goLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.goLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    handleSortChange(value) {
      // Implement sorting logic here
    },
    successMsg(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: msg,
        timeout: 5000,
        Top: true
      };
      this.tableData = [];
      this.totalItems = 0;
      this.getexpense_list();
    },
    errorMsg(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: msg,
        timeout: 5000,
        Top: true
      };
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    displayFormatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${day}/${month}/${year}`;
    }
  }
};
